create table if not exists public.package_presets ( id uuid primary key default gen_random_uuid(), name text not null check (char_length(btrim(name)) between 1 and 60), revisions text not null default 'none' check (revisions in ('none', 'approve', 'full')), revision_rounds integer check (revision_rounds is null or revision_rounds between 1 and 20), thumbnails boolean not null default false, graphics boolean not null default false, posting_mode text not null default 'weekdays' check (posting_mode in ('weekdays', 'daily', 'per_week')), posting_weekdays smallint[] not null default '{}' check (posting_weekdays <@ array[1,2,3,4,5,6,7]::smallint[]), videos_per_week integer check (videos_per_week is null or videos_per_week between 1 and 21), double_post_weekdays smallint[] not null default '{}' check (double_post_weekdays <@ array[1,2,3,4,5,6,7]::smallint[]), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint package_presets_rounds_need_full check (revision_rounds is null or revisions = 'full'), constraint package_presets_weekdays_need_days check (posting_mode <> 'weekdays' or cardinality(posting_weekdays) > 0), constraint package_presets_per_week_needs_count check (posting_mode <> 'per_week' or videos_per_week is not null) ); create unique index if not exists package_presets_name_unique on public.package_presets (lower(btrim(name))); alter table public.package_presets enable row level security; drop policy if exists "package_presets: management" on public.package_presets; create policy "package_presets: management" on public.package_presets for all using (public.is_management()) with check (public.is_management()); create table if not exists public.client_packages ( client_id uuid primary key references public.clients (id) on delete cascade, preset_id uuid references public.package_presets (id) on delete set null, revisions text not null default 'none' check (revisions in ('none', 'approve', 'full')), revision_rounds integer check (revision_rounds is null or revision_rounds between 1 and 20), thumbnails boolean not null default false, graphics boolean not null default false, posting_mode text not null default 'weekdays' check (posting_mode in ('weekdays', 'daily', 'per_week')), posting_weekdays smallint[] not null default '{}' check (posting_weekdays <@ array[1,2,3,4,5,6,7]::smallint[]), videos_per_week integer check (videos_per_week is null or videos_per_week between 1 and 21), double_post_weekdays smallint[] not null default '{}' check (double_post_weekdays <@ array[1,2,3,4,5,6,7]::smallint[]), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), updated_by uuid references public.profiles (id) on delete set null, constraint client_packages_rounds_need_full check (revision_rounds is null or revisions = 'full'), constraint client_packages_weekdays_need_days check (posting_mode <> 'weekdays' or cardinality(posting_weekdays) > 0), constraint client_packages_per_week_needs_count check (posting_mode <> 'per_week' or videos_per_week is not null) ); alter table public.client_packages enable row level security; drop policy if exists "client_packages: management" on public.client_packages; create policy "client_packages: management" on public.client_packages for all using (public.can_manage_client(client_id)) with check (public.can_manage_client(client_id)); drop policy if exists "client_packages: team reads assigned" on public.client_packages; create policy "client_packages: team reads assigned" on public.client_packages for select using (public.can_see_client(client_id)); drop policy if exists "client_packages: client reads own" on public.client_packages; create policy "client_packages: client reads own" on public.client_packages for select using ( public.current_role() = 'client' and client_id = public.current_client_id() ); create or replace function public.packages_touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at := now(); return new; end; $$; drop trigger if exists client_packages_touch_updated_at on public.client_packages; create trigger client_packages_touch_updated_at before update on public.client_packages for each row execute procedure public.packages_touch_updated_at(); drop trigger if exists package_presets_touch_updated_at on public.package_presets; create trigger package_presets_touch_updated_at before update on public.package_presets for each row execute procedure public.packages_touch_updated_at();
